		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// BLAS SYRK: C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Optimizations compared to the original kernel:
//  - All loop nests are expressed with noarr::traverser + for_dims / for_each.
//  - For the rank‑k update, the loop order is changed to k → i → j.
//    This improves reuse of A(i,k): we load A(i,k) once per (i,k) and reuse it
//    across all j in the inner loop.
//  - The triangular condition j <= i is checked only in the innermost loop,
//    but indices i and k are hoisted out of that loop to reduce index extraction
//    overhead.
//  - Scaling C by beta is done in a separate traversal, with i hoisted so that
//    the row index is computed once per row.
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// Step 1: C[i][j] *= beta for j <= i (scale lower triangle)
	// ------------------------------------------------------------------
	traverser(C).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, remaining dimension(s) include 'j'
		auto state_i = trav_i.state();
		const auto i = get_index<'i'>(state_i);

		trav_i.for_each([&](auto state) {
			const auto j = get_index<'j'>(state);
			if (j <= i) {
				C[state] *= beta;
			}
		});
	});

	// ------------------------------------------------------------------
	// Step 2: C[i][j] += alpha * A[i][k] * A[j][k] for all k, j <= i
	//
	// We iterate in the order:
	//   k (outer) → i (middle) → j (inner)
	//
	// For a fixed (k, i), we:
	//   - load A[i][k] once into a_ik_scaled = alpha * A[i][k]
	//   - iterate over all j and for j <= i, update C[i][j] using A[j][k]
	//
	// This improves data locality for the A(:,k) column and reduces
	// redundant loads of A[i][k] compared to loading it inside the j-loop.
	// ------------------------------------------------------------------
	traverser(C, A).template for_dims<'k'>([&](auto trav_k) {
		// trav_k has 'k' fixed, remaining dimensions include 'i' and 'j'
		trav_k.template for_dims<'i'>([&](auto trav_ik) {
			// trav_ik has 'k' and 'i' fixed, remaining dimension is 'j'
			auto state_ik = trav_ik.state();
			const auto i = get_index<'i'>(state_ik);
			// k is only needed to compute A[j][k] via state_ik; we do not
			// explicitly read it in the inner loop.

			// Load A[i][k] once and scale by alpha; reused for all j
			const num_t a_ik = A[state_ik];
			const num_t a_ik_scaled = alpha * a_ik;

			trav_ik.for_each([&](auto state) {
				// state has 'i', 'j', and 'k'; 'i' and 'k' match state_ik
				const auto j = get_index<'j'>(state);

				if (j <= i) {
					// Build a state for A[j][k] by replacing the 'i' index
					// in state_ik with j. This state only carries 'i' and 'k',
					// which are exactly the dimensions A uses.
					auto state_jk = noarr::update_index<'i'>(state_ik, [=](auto) { return j; });
					const num_t a_jk = A[state_jk];

					// C[state] uses (i,j); the 'k' index present in 'state'
					// is ignored by C's structure.
					C[state] += a_ik_scaled * a_jk;
				}
			});
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
