	// A: i x k  (logical)
	// layout: scalar ^ k_vec ^ i_vec  => 'i' is outer, 'k' is inner (row-major in k)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A) {
	// C: i x j, length(i) = N, length(j) = N
	// A: i x k, length(i) = N, length(k) = M
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// Pre-compute lengths once (avoid doing it inside the loops)
	const std::size_t n_len = A | get_length<'i'>(); // N
	const std::size_t m_len = A | get_length<'k'>(); // M

	// A[i][k] = ( (i * k + 1) % n ) / n;
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	// Note: we intentionally use m_len from A's second dimension (M),
	// matching the original implementation.
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// BLAS SYRK (lower triangle):
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Original algorithm did:
// 1) C[i][j] *= beta; for j <= i
// 2) C[i][j] += alpha * sum_k A[i][k] * A[j][k]; for j <= i
//
// We fuse both steps into a single pass per (i,j) and
// reorder loops to:
//   for i
//     for j
//       for k
// This order gives:
//   - good locality for C: 'i' outer, 'j' inner  => C row written contiguously
//   - good locality for both A[i][k] and A[j][k]: 'k' is inner in A,
//     so the dot-product over k walks both A rows contiguously.
// We also:
//   - avoid constructing temporary states via update_index
//   - compute A[j][k] through a cheap renamed view of A
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	// Create a view of A where the row dimension is named 'j' instead of 'i'.
	// This lets us access A[j][k] as A_by_j[state] without rebuilding states.
	auto A_by_j = A ^ noarr::rename<'i', 'j'>();

	#pragma scop
	traverser(C, A, A_by_j).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed; remaining varying dimensions: 'j' and 'k'

		// Iterate over all columns j for the current row i
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			// trav_ij has 'i' and 'j' fixed; remaining varying dimension: 'k'
			auto state_ij = trav_ij.state();
			auto [i, j] = get_indices<'i', 'j'>(state_ij);

			// Only update the lower triangle (including diagonal)
			if (j > i)
				return;

			// Compute dot product over k: sum_k A[i][k] * A[j][k]
			num_t sum = 0;

			// For this fixed (i,j), trav_ij.for_each iterates over 'k'
			trav_ij.for_each([&](auto state) {
				// state has indices (i, j, k)
				// A uses (i,k); A_by_j uses (j,k); extra indices are ignored.
				sum += A[state] * A_by_j[state];
			});

			// Fused update: C[i][j] = beta * C[i][j] + alpha * sum
			num_t cij = C[state_ij];
			C[state_ij] = beta * cij + alpha * sum;
		});
	});
	#pragma endscop
}

