// computation kernel
//
// BLAS SYRK:
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Layouts (physical):
//   C: scalar<num_t> ^ vector<'j'> ^ vector<'i'>   // j outer, i inner (columns of C are contiguous)
//   A: scalar<num_t> ^ vector<'k'> ^ vector<'i'>   // k outer, i inner (columns of A are contiguous)
//
// To exploit these layouts, we traverse:
//
//   for j = 0..N-1           // fix column j of C and row j of A
//     for i = j..N-1         // walk down column j of C (i is inner dim -> contiguous)
//       C[i,j] *= beta
//     for k = 0..M-1
//       a_jk = A[j,k]        // scalar reused for all i in this (j,k)
//       for i = j..N-1       // contiguous in both C (column j) and A (column k)
//         C[i,j] += alpha * A[i,k] * a_jk
//
// This keeps all inner loops along the physically inner dimension 'i' for both C and A,
// improving cache behavior and memory throughput compared to an i-major traversal.
//
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// 1) Scale the lower triangle of C by beta: C[i,j] *= beta, j <= i
	//    Traverse C column-major: outer over 'j', inner contiguous over 'i'.
	// ------------------------------------------------------------------
	traverser(C)
		.template for_dims<'j'>([=](auto trav_j) {
			// trav_j has dimension 'j' fixed; remaining free dim is 'i'
			auto j_state = trav_j.state();
			auto j = get_index<'j'>(j_state);

			trav_j.for_each([=](auto state) {
				// state has ('i','j'); 'j' is fixed for this column
				auto i = get_index<'i'>(state);

				// Only update the lower triangle j <= i
				if (i >= j) {
					C[state] *= beta;
				}
			});
		});

	// ------------------------------------------------------------------
	// 2) Symmetric rank-k update:
	//      C[i,j] += alpha * sum_k A[i,k] * A[j,k]   for all j <= i
	//
	//    We again traverse column-major in C:
	//      outer: j
	//        inner-1: k
	//          inner-2: i (contiguous in both C and A)
	//
	//    For a fixed (j,k) we pre-load A[j,k] once and reuse it for all i.
	// ------------------------------------------------------------------
	traverser(C, A)
		.template for_dims<'j'>([=](auto trav_j) {
			// trav_j has 'j' fixed, remaining free dims are 'i' (from C/A) and 'k' (from A)
			auto j_state = trav_j.state();
			auto j = get_index<'j'>(j_state); // current column index

			// Loop over k (columns of A)
			trav_j.template for_dims<'k'>([=](auto trav_k) {
				// trav_k has 'j' and 'k' fixed; remaining free dim is 'i'
				auto jk_state = trav_k.state();
				auto k = get_index<'k'>(jk_state);

				// Pre-load A[j][k] and combine with alpha; reused for all i in this (j,k).
				//
				// We build a state with indices (i=j, k) for A. C also ignores 'k', so this
				// state is only used when indexing A.
				auto a_jk_state = idx<'i', 'k'>(j, k);
				num_t a_jk = A[a_jk_state];
				num_t alpha_a_jk = alpha * a_jk;

				// Now walk i down the column j of C and down column k of A.
				// Both C[i,j] and A[i,k] are contiguous in 'i'.
				trav_k.for_each([=](auto state) {
					// state has ('i','j','k'); here 'j' and 'k' are fixed for this lambda
					auto i = get_index<'i'>(state);

					// Restrict to the lower triangle j <= i
					if (i >= j) {
						// A[i][k]: j is ignored by A, only (i,k) matter
						num_t a_ik = A[state];

						// C[i][j] update
						C[state] += alpha_a_jk * a_ik;
					}
				});
			});
		});

	#pragma endscop
}

} // namespace

