// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// The traversal is organized as:
//   for i
//     scale C[i][j] by beta for all j <= i
//     for k
//       let t = alpha * A[i][k]      (invariant across j for fixed i,k)
//       for j
//         if (j <= i)
//           C[i][j] += t * A[j][k]
//
