//   - C row-major (j inner) access in the innermost loop
//   - Reuses A[i][k] across all j for fixed (i,k) by hoisting it out of the j-loop
//   - Still uses Noarr traversers for all loop nests
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop
	// Traverse in 'i' first (rows of C / A)
