			// trav_ij has both 'i' and 'j' fixed (no 'k')
			const auto state_ij = trav_ij.state();
			const std::size_t j = get_index<'j'>(state_ij);

			if (j <= i) {
				// C uses dimensions (i,j); state_ij provides both
				C[state_ij] *= beta;
			}
		});

		// --------------------------------------------------------------------
		// 2) Accumulate alpha * A[i][k] * A[j][k] into C[i][j] for all k, j<=i
		//
		// Loop order: i (outer), k (middle), j (inner)
		// - This matches the original algorithmic order.
		// - We hoist A[i][k] outside the j-loop to avoid recomputing it.
		// --------------------------------------------------------------------
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed
			const auto state_ik = trav_ik.state();
			const std::size_t k = get_index<'k'>(state_ik);

			// A[i][k] is invariant over j for this (i,k)
			const num_t a_ik = A[state_ik];
			const num_t alpha_a_ik = alpha * a_ik;

			// Now iterate over all j for this fixed (i,k)
			trav_ik.template for_dims<'j'>([&](auto trav_ijk) {
				// trav_ijk has 'i', 'j', 'k' fixed (no remaining dimensions)
				const auto state_ijk = trav_ijk.state();
				const std::size_t j = get_index<'j'>(state_ijk);

				// Process only the lower triangle (j <= i)
				if (j <= i) {
					// Access A[j][k]; A is logically i x k, so use (i=j, k)
					// Build a minimal state containing just the indices needed by A.
					const auto state_jk = noarr::idx<'i', 'k'>(j, k);
					const num_t a_jk = A[state_jk];

					// C uses (i,j); state_ijk contains both and ignores 'k'
					C[state_ijk] += alpha_a_ik * a_jk;
				}
			});
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t alpha;
	num_t beta;

	// set lengths for each structure
	auto set_lengths_C = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);
	auto set_lengths_A = noarr::set_length<'i'>(n) ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths_C);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths_A);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syrk(alpha, beta, C.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to print C in i-major order
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
